import { useState } from 'react'
import { deleteCandidate, getCandidateById, type Candidate } from '@/entities/candidate'
import { ApiError } from '@/shared/api/client'

type VerifyState = 'idle' | 'verifying' | 'blocked' | 'ready'

const BLOCKED_STATUSES = new Set(['ACTIVE', 'SUBMITTED'])

export function useDeleteCandidate(onSuccess?: () => void) {
  const [isOpen, setIsOpen]                     = useState(false)
  const [isLoading, setIsLoading]               = useState(false)
  const [verifyState, setVerifyState]           = useState<VerifyState>('idle')
  const [error, setError]                       = useState<string | null>(null)
  const [candidateToDelete, setCandidateToDelete] = useState<Candidate | null>(null)

  const handleOpen = async (candidate: Candidate) => {
    setCandidateToDelete(candidate)
    setError(null)
    setIsOpen(true)
    setVerifyState('verifying')

    try {
      const fresh = await getCandidateById(candidate.id)
      if (BLOCKED_STATUSES.has(fresh.status ?? '')) {
        setVerifyState('blocked')
        setCandidateToDelete(fresh)
      } else {
        setVerifyState('ready')
        setCandidateToDelete(fresh)
      }
    } catch {
      // If verification fails, fall back to the status we already have
      if (BLOCKED_STATUSES.has(candidate.status ?? '')) {
        setVerifyState('blocked')
      } else {
        setVerifyState('ready')
      }
    }
  }

  const handleClose = () => {
    setIsOpen(false)
    setError(null)
    setCandidateToDelete(null)
    setVerifyState('idle')
  }

  const handleConfirm = async () => {
    if (!candidateToDelete || verifyState !== 'ready') return

    try {
      setError(null)
      setIsLoading(true)

      await deleteCandidate(candidateToDelete.id)

      handleClose()
      onSuccess?.()
    } catch (err: unknown) {
      if (err instanceof ApiError) {
        setError(err.message)
      } else {
        setError(err instanceof Error ? err.message : 'Failed to delete candidate')
      }
    } finally {
      setIsLoading(false)
    }
  }

  return {
    isOpen,
    isLoading,
    verifyState,
    error,
    candidateToDelete,
    handleOpen,
    handleClose,
    handleConfirm,
  }
}
